#include "../Source/Presets.h"
#include <iostream>
#include <memory>
#include <stdexcept>
int main(){try{float worst=0;bool excess=false;for(float sr:{48000.f,96000.f})for(auto& preset:knc::factoryPresets){if(preset.values[knc::Clip]==100&&(preset.values[knc::Comp]<22||preset.values[knc::Comp]>46))throw std::runtime_error("Aggressive compressor outside 22-46 percent");
 for(int id:{knc::Trans,knc::Comp,knc::Sat,knc::Sub,knc::Air,knc::Clip,knc::Bit,knc::Delay,knc::Reverb,knc::Chorus,knc::Width,knc::Low,knc::Mid,knc::High,knc::Mix})if(preset.values[id]==0)throw std::runtime_error("Extreme recipe has an unused knob");
 auto engine=std::make_unique<knc::Engine>();engine->prepare(sr,preset.values);float peak=0;uint32_t noise=1234567;
 for(int block=0;block<int(sr*3)/256;++block){float left[256],right[256];for(int n=0;n<256;++n){int index=block*256+n;float t=index/sr;noise=noise*1664525u+1013904223u;float random=(int32_t(noise)/2147483648.f);float drive=t<1?1.f:t<2?2.f:0.f;float signal=.65f*std::sin(2*knc::pi*55*t)+.5f*std::sin(2*knc::pi*991*t)+.35f*random;if(index%997==0)signal=2;left[n]=drive*signal;right[n]=drive*(.6f*signal+.4f*std::sin(2*knc::pi*317*t));}float* channels[]={left,right};engine->process(channels,2,256);for(int n=0;n<256;++n)for(auto* channel:channels){if(!std::isfinite(channel[n]))throw std::runtime_error("Nonfinite extreme preset output");peak=std::max(peak,std::abs(channel[n]));}}
 std::cout<<sr<<" "<<preset.category<<" / "<<preset.name<<" peak="<<peak<<"\n";if(peak>.98f)excess=true;worst=std::max(worst,peak);
 }// Repeated changes retain effect tails and smooth controls; test mono and stereo.
 for(int channels:{1,2}){auto transition=std::make_unique<knc::Engine>();transition->prepare(48000,knc::factoryPresets.back().values);for(auto& preset:knc::factoryPresets){transition->targets(preset.values);for(int block=0;block<50;++block){float left[256],right[256];for(int n=0;n<256;++n){float t=(block*256+n)/48000.f;left[n]=.8f*std::sin(2*knc::pi*73*t)+.6f*std::sin(2*knc::pi*1703*t);right[n]=-left[n];if(n==0&&block%9==0)left[n]=right[n]=4;}float* data[]={left,right};transition->process(data,channels,256);for(int c=0;c<channels;++c){for(int n=0;n<256;++n){if(!std::isfinite(data[c][n]))throw std::runtime_error("Nonfinite preset transition");worst=std::max(worst,std::abs(data[c][n]));if(std::abs(data[c][n])>.98f)excess=true;}}}}}
 std::cout<<"Peak audit maximum="<<worst<<"\n";if(excess)throw std::runtime_error("Extreme preset exceeds ceiling");std::cout<<"PASS: all 50 presets and mono/stereo transitions use the new controls, finite processing and output headroom; maximum="<<worst<<"\n";}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}return 0;}
